private void pop(final String descriptor) {
    if (descriptor == null) {
        throw new IllegalArgumentException("Descriptor cannot be null");
    }

    int argumentCount = 0;
    for (int i = 0; i < descriptor.length(); i++) {
        char c = descriptor.charAt(i);
        if (c == 'B' || c == 'C' || c == 'S' || c == 'I') {
            argumentCount++;
        } else if (c == 'J' || c == 'F' || c == 'D') {
            argumentCount += 2;
        } else if (c == 'L' || c == '[') {
            // Skip the fully qualified class name or array type
            while (i < descriptor.length() && descriptor.charAt(i) != ';') {
                i++;
            }
            argumentCount += 2; // Each object reference takes up two slots in the stack
            i++; // Skip the semicolon
        } else if (c == '(') {
            // Skip the parameter descriptor
            int count = 1;
            while (count > 0) {
                i++;
                char paramChar = descriptor.charAt(i);
                if (paramChar == '(') {
                    count++;
                } else if (paramChar == ')') {
                    count--;
                } else if (paramChar == 'B' || paramChar == 'C' || paramChar == 'S' || paramChar == 'I') {
                    argumentCount++;
                } else if (paramChar == 'J' || paramChar == 'F' || paramChar == 'D') {
                    argumentCount += 2;
                } else if (paramChar == 'L' || paramChar == '[') {
                    while (i < descriptor.length() && descriptor.charAt(i) != ';') {
                        i++;
                    }
                    argumentCount += 2;
                    i++;
                }
            }
        }
    }

    // Pop the specified number of abstract types from the output frame stack
    for (int i = 0; i < argumentCount; i++) {
